owner := func(id string, t int64) int {
	lm := st.landmarks[id]
	if lm == nil {
		return 0
	}
	return lm.occurrenceAt(t)
}
results, rerr, reason := replayObservations(replayFrames, owner, seeds, st.config.MergeDistance)
